export function spectroscopyEvidence(record){const r=record.result,s=r.selection||{};switch(record.action){case'spin_resonance_lab':return `Dimension =${r.dimension}; The strongest transition =${num(s.dominantFrequency)} GHz; positive frequency absorption weight =${num(s.totalWeight)}; Given effective spin parameters, non-automatic material fitting`;case'andreev_lab':return `Ree=${num(s.normalReflection)}；Rhe=${num(s.andreevReflection)}；G=${num(s.conductanceQuantum)} e²/h（ contains two spins); validity =${s.defined?"defined":"undefined"}; numerical status =${s.numericallyResolved?"has passed the current criterion":"needs verification"}; Flux residual =${num(r.checks.fluxResidual)}; artificial absorption Aη=${num(s.regulatorAbsorption)}; η difference =${num(r.checks.etaDifference)}`;case'atomic_spectra_lab':return `${r.parameters.configuration}; Initial/last dimension =${r.dimensions.initial}/${r.dimensions.final}；⟨S²⟩=${num(r.ground.S2)}；⟨L²⟩=${num(r.ground.L2)}; Polarized =${r.parameters.polarization}; The energy is relative to the center of gravity of the final state and the intensity omits the common radial factor`;default:return null;}}
